/**
 * /sitemap — human-readable index of every public Flintmere surface.
 *
 * Distinct from `/sitemap.xml` (machine-readable, generated by
 * `apps/scanner/src/app/sitemap.ts`). This is the visitor-facing
 * orientation page — three hosts, the routes on each, the legal
 * footprint, the machine endpoints.
 *
 * Voice register: same as /about — declarative, team voice,
 * restraint-as-composition. One bracket moment in the hero.
 *
 * Source of truth: `apps/scanner/src/lib/host-routing.ts` (host
 * assignments) + `apps/scanner/src/app/sitemap.ts` (XML route list).
 * Adding a new public route: update host-routing.ts MARKETING_ROUTES
 * (or SCANNER_ROUTES / STANDARDS_ROUTES), update sitemap.ts, then
 * mention it here.
 */

export const dynamic = 'force-static';
