function HostSection({
  hostname,
  role,
  description,
  links,
  headingId,
}: {
  hostname: string;
  role: string;
  description: string;
  links: RouteLink[];
  headingId: string;
}) {
  return (
    <section
      aria-labelledby={headingId}
      style={{ marginTop: 'clamp(64px, 8vw, 112px)' }}
    >
      <p
        className="font-mono uppercase"
        style={{
          fontSize: 'clamp(11px, 1vw, 13px)',
          letterSpacing: '0.18em',
          color: 'var(--color-mute)',
          marginBottom: 'clamp(16px, 2vw, 24px)',
        }}
      >
        <span aria-hidden="true">// </span>
        {hostname}
      </p>
      <h2
        id={headingId}
        className="font-sans font-medium tracking-[-0.03em] leading-[1.05] text-[color:var(--color-ink)]"
        style={{
          fontSize: 'clamp(28px, 3.6vw, 48px)',
          marginBottom: 'clamp(16px, 2vw, 24px)',
        }}
      >
        {role}
      </h2>
      <p
        className="font-sans"
        style={{
          fontSize: 'clamp(15px, 1.1vw, 17px)',
          lineHeight: 1.55,
          color: 'var(--color-mute)',
          maxWidth: '52ch',
          marginBottom: 'clamp(28px, 3.5vw, 48px)',
        }}
      >
        {description}
      </p>
      <ul
        className="list-none"
        style={{
          borderTop: '1px solid var(--color-line)',
        }}
      >
        {links.map((link) => (
          <li
            key={`${link.href}__${link.label}`}
            style={{
              borderBottom: '1px solid var(--color-line)',
              paddingTop: 'clamp(14px, 1.6vw, 20px)',
              paddingBottom: 'clamp(14px, 1.6vw, 20px)',
            }}
          >
            <Link
              href={link.href}
              className="font-sans text-[color:var(--color-ink)] hover:text-[color:var(--color-accent)] transition-colors duration-[var(--duration-instant)]"
              style={{
                fontSize: 'clamp(16px, 1.2vw, 19px)',
                lineHeight: 1.4,
                textDecoration: 'none',
              }}
            >
              {link.label}
            </Link>
            {link.note ? (
              <p
                className="font-sans"
                style={{
                  fontSize: 'clamp(13px, 0.95vw, 14px)',
                  lineHeight: 1.5,
                  color: 'var(--color-mute)',
                  marginTop: '6px',
                  maxWidth: '64ch',
                }}
              >
                {link.note}
              </p>
            ) : null}
          </li>
        ))}
      </ul>
    </section>
  );
}

